update public.lessons
set content='{"intro": "Esta aula transforma «Prazos máximos e deferimento tácito» numa competência de trabalho. No final, deverá conseguir reconhecer a situação, localizar a informação relevante, fazer as verificações essenciais, explicar o resultado ao cliente com rigor e identificar quando é necessária validação especializada.", "sections": [{"title": "O que deve dominar", "body": "O objetivo desta aula é dominar «Prazos máximos e deferimento tácito» no contexto de Licenciamento 2026 — Prazos e Aceleração. O formando deve conseguir explicar o conceito, identificar a documentação ou informação necessária, reconhecer os principais riscos e saber qual é o próximo passo profissional."}, {"title": "Nota temporal · agosto de 2026", "body": "A revisão aprovada pelo Decreto-Lei n.º 108/2026 não deve ser tratada como já plenamente aplicável nesta data: o Decreto-Lei n.º 155-B/2026 prorrogou a entrada em vigor das alterações para 1 de outubro de 2026. Sempre que a aula descreva o novo regime, deve distingui-lo do regime em vigor até essa data e confirmar o regime transitório no caso concreto."}, {"title": "Como aplicar na prática", "body": "Transforme «Prazos máximos e deferimento tácito» num procedimento: 1) definir o objetivo do cliente; 2) recolher fontes adequadas; 3) verificar atualidade e correspondência; 4) comparar com a realidade e outras fontes; 5) classificar divergências; 6) comunicar apenas conclusões suportadas; 7) encaminhar o que exigir competência especializada."}, {"title": "O que confirmar antes de concluir", "body": "Evite tratar «Prazos máximos e deferimento tácito» como uma formalidade. Pergunte sempre o que o dado/documento prova, o que não prova, se está atual e que efeito tem no negócio."}, {"title": "Exemplo profissional", "body": "Exemplo profissional: perante uma informação relacionada com «Prazos máximos e deferimento tácito» que não coincide com outro documento ou com a realidade, o consultor regista a divergência, não escolhe a versão mais conveniente e define a validação necessária antes de a apresentar como facto."}, {"title": "Erros que deve evitar", "body": "• Repetir informação do proprietário como se estivesse verificada.\n• Usar um documento para provar matéria que pertence a outra fonte.\n• Ignorar a data, validade ou versão consultada.\n• Transformar uma estimativa ou possibilidade em certeza comercial.\n• Omitir uma divergência material por receio de dificultar o negócio."}, {"title": "Limite profissional", "body": "O consultor deve distinguir factos documentados, informação do cliente, estimativas comerciais e matérias que exigem validação especializada. Quando uma conclusão ultrapassa a sua competência, deve identificá-la como pendente e encaminhá-la."}], "takeaway": "Competência concluída: saber tratar «Prazos máximos e deferimento tácito» com fonte, método, limites profissionais e comunicação transparente.", "case_title": "Aplicação prática", "case_body": "Exemplo profissional: perante uma informação relacionada com «Prazos máximos e deferimento tácito» que não coincide com outro documento ou com a realidade, o consultor regista a divergência, não escolhe a versão mais conveniente e define a validação necessária antes de a apresentar como facto."}'::jsonb,
    source_url='https://diariodarepublica.pt/dr/legislacao-consolidada/decreto-lei/1999-34567875-45232875',
    verified_at=date '2026-08-20',
    legal_sensitive=true
where id=91;
update public.lessons
set content='{"intro": "Esta aula transforma «Saneamento e apreciação liminar» numa competência de trabalho. No final, deverá conseguir reconhecer a situação, localizar a informação relevante, fazer as verificações essenciais, explicar o resultado ao cliente com rigor e identificar quando é necessária validação especializada.", "sections": [{"title": "O que deve dominar", "body": "O objetivo desta aula é dominar «Saneamento e apreciação liminar» no contexto de Licenciamento 2026 — Prazos e Aceleração. O formando deve conseguir explicar o conceito, identificar a documentação ou informação necessária, reconhecer os principais riscos e saber qual é o próximo passo profissional."}, {"title": "Nota temporal · agosto de 2026", "body": "A revisão aprovada pelo Decreto-Lei n.º 108/2026 não deve ser tratada como já plenamente aplicável nesta data: o Decreto-Lei n.º 155-B/2026 prorrogou a entrada em vigor das alterações para 1 de outubro de 2026. Sempre que a aula descreva o novo regime, deve distingui-lo do regime em vigor até essa data e confirmar o regime transitório no caso concreto."}, {"title": "Como aplicar na prática", "body": "Transforme «Saneamento e apreciação liminar» num procedimento: 1) definir o objetivo do cliente; 2) recolher fontes adequadas; 3) verificar atualidade e correspondência; 4) comparar com a realidade e outras fontes; 5) classificar divergências; 6) comunicar apenas conclusões suportadas; 7) encaminhar o que exigir competência especializada."}, {"title": "O que confirmar antes de concluir", "body": "Evite tratar «Saneamento e apreciação liminar» como uma formalidade. Pergunte sempre o que o dado/documento prova, o que não prova, se está atual e que efeito tem no negócio."}, {"title": "Exemplo profissional", "body": "Exemplo profissional: perante uma informação relacionada com «Saneamento e apreciação liminar» que não coincide com outro documento ou com a realidade, o consultor regista a divergência, não escolhe a versão mais conveniente e define a validação necessária antes de a apresentar como facto."}, {"title": "Erros que deve evitar", "body": "• Repetir informação do proprietário como se estivesse verificada.\n• Usar um documento para provar matéria que pertence a outra fonte.\n• Ignorar a data, validade ou versão consultada.\n• Transformar uma estimativa ou possibilidade em certeza comercial.\n• Omitir uma divergência material por receio de dificultar o negócio."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer os impostos e saber que informação é necessária para uma simulação, mas não deve transformar exemplos em aconselhamento fiscal individual. Taxas, isenções e enquadramentos devem ser confirmados na legislação vigente e, quando necessário, com contabilista ou fiscalista."}], "takeaway": "Competência concluída: saber tratar «Saneamento e apreciação liminar» com fonte, método, limites profissionais e comunicação transparente.", "case_title": "Aplicação prática", "case_body": "Exemplo profissional: perante uma informação relacionada com «Saneamento e apreciação liminar» que não coincide com outro documento ou com a realidade, o consultor regista a divergência, não escolhe a versão mais conveniente e define a validação necessária antes de a apresentar como facto."}'::jsonb,
