update public.lessons
set content='{"intro": "Esta aula transforma «Antes de 1951: cuidado com simplificações» numa competência de trabalho. No final, deverá conseguir reconhecer a situação, localizar a informação relevante, fazer as verificações essenciais, explicar o resultado ao cliente com rigor e identificar quando é necessária validação especializada.", "sections": [{"title": "O que deve dominar", "body": "Imóveis antigos exigem reconstrução documental: data provável de edificação, histórico matricial/registral, processos municipais, ampliações posteriores e regime aplicável à época. A expressão ''anterior a 1951'' não deve ser usada como atalho universal para dispensar qualquer verificação."}, {"title": "Como aplicar na prática", "body": "Recolher documentos antigos, certidões/certidões municipais quando disponíveis, plantas, fotografias aéreas ou outros elementos pertinentes; distinguir construção originária de ampliações ou anexos posteriores; verificar o regime e prática municipal aplicáveis ao caso."}, {"title": "O que confirmar antes de concluir", "body": "Uma construção originária antiga pode coexistir com obras posteriores sujeitas a controlo urbanístico. A idade do edifício principal não regulariza automaticamente anexos ou ampliações."}, {"title": "Exemplo profissional", "body": "Exemplo: casa principal antiga e anexo inscrito fiscalmente décadas depois. Analise cada componente e a respetiva cronologia."}, {"title": "Erros que deve evitar", "body": "• Repetir informação do proprietário como se estivesse verificada.\n• Usar um documento para provar matéria que pertence a outra fonte.\n• Ignorar a data, validade ou versão consultada.\n• Transformar uma estimativa ou possibilidade em certeza comercial.\n• Omitir uma divergência material por receio de dificultar o negócio."}, {"title": "Limite profissional", "body": "O consultor deve distinguir factos documentados, informação do cliente, estimativas comerciais e matérias que exigem validação especializada. Quando uma conclusão ultrapassa a sua competência, deve identificá-la como pendente e encaminhá-la."}], "takeaway": "Competência concluída: saber tratar «Antes de 1951: cuidado com simplificações» com fonte, método, limites profissionais e comunicação transparente.", "case_title": "Aplicação prática", "case_body": "Exemplo: casa principal antiga e anexo inscrito fiscalmente décadas depois. Analise cada componente e a respetiva cronologia."}'::jsonb,
    source_url='https://diariodarepublica.pt/dr/legislacao-consolidada/decreto-lei/1999-34567875-45232375',
    verified_at=date '2026-08-20',
    legal_sensitive=true
where id=107;
